    deps=re.findall(r'"([^"]+)"',p.split('dependencies = [')[1].split(']')[0]) if 'dependencies = [' in p else []
    pk[m.group(1)+' '+m.group(2)]=deps
def users(target):
    return [k for k,v in pk.items() if any(d==target or d.startswith(target+' ') for d in v)]
for t in ['getrandom 0.4.3','tempfile']:
    print(t,'<-',users(t))
for u in users('getrandom 0.4.3'):
    print(u,'<-',users(u.split()[0]))
